package com.gymmind.membership.api; import com.gymmind.membership.application.*; import com.gymmind.shared.api.ApiResponse; import com.gymmind.shared.security.CurrentActorProvider; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; @RestController @RequestMapping("/api/v1/membership-packages") @SecurityRequirement(name="bearerAuth") public class MembershipPackageController{private final MembershipPackageService service;private final CurrentActorProvider actors;public MembershipPackageController(MembershipPackageService s,CurrentActorProvider a){service=s;actors=a;}@PostMapping @ResponseStatus(HttpStatus.CREATED)public ApiResponse<MembershipPackageView>create(@Valid@RequestBody CreateRequest r){return ApiResponse.success(service.create(actors.requireCurrent(),new CreateMembershipPackageCommand(null,r.name(),r.entitlementType(),r.entitlementCount(),r.validDays(),r.price(),r.currency())));}@GetMapping("/{id}")public ApiResponse<MembershipPackageView>find(@PathVariable Long id){return ApiResponse.success(service.find(actors.requireCurrent(),id));}public record CreateRequest(@NotBlank String name,@NotBlank String entitlementType,Integer entitlementCount,Integer validDays,BigDecimal price,@NotBlank String currency){}}
